mapper.select:
SELECT fb.bill_id AS billId, fb.bill_no AS billNo, fb.owner_id AS ownerId, fb.owner_name AS ownerName, fb.room_id AS roomId, fb.item_id AS itemId, fb.item_name AS itemName, fb.bill_year AS billYear, fb.bill_month AS billMonth, fb.receivable_amount AS receivableAmount, fb.received_amount AS receivedAmount, fb.unpaid_amount AS unpaidAmount, fb.due_date AS dueDate, fb.bill_status AS billStatus, fb.create_by AS createBy, fb.create_time AS createTime, fb.update_by AS updateBy, fb.update_time AS updateTime, fb.remark AS remark, c.community_name AS communityName, b.building_name AS buildingName, u.unit_name AS unitName, r.room_name AS roomName, o.owner_real_name AS ownerRealName, o.owner_phone_number AS ownerPhoneNumber FROM community_fee_bill fb LEFT JOIN owner o ON o.owner_id = fb.owner_id LEFT JOIN room r ON r.room_id = fb.room_id LEFT JOIN community c ON c.community_id = r.community_id LEFT JOIN building b ON b.building_id = r.building_id LEFT JOIN unit u ON u.unit_id = r.unit_id LEFT JOIN community_fee_item fi ON fi.item_id = fb.item_id
AND c.community_id = #{q.communityId}
AND fb.bill_no LIKE CONCAT('%', #{q.billNo}, '%')
AND fb.owner_id = #{q.ownerId}
AND (fb.owner_name LIKE CONCAT('%', #{q.ownerName}, '%') OR o.owner_real_name LIKE CONCAT('%', #{q.ownerName}, '%'))
AND fb.room_id = #{q.roomId}
AND fb.item_id = #{q.itemId}
AND fb.item_name LIKE CONCAT('%', #{q.itemName}, '%')
AND fb.bill_year = #{q.billYear}
AND fb.bill_month = #{q.billMonth}
AND fb.bill_status = #{q.billStatus}
ORDER BY fb.create_time DESC, fb.bill_id DESC

